from pathlib import Path
import hashlib,json,subprocess,sys
R=Path(__file__).resolve().parents[1]
paths=[p for p in (R/'src/main/resources').rglob('*') if p.is_file()]+[R/'src/main/java/org/slavicmyths/client/NochnitsaMesh.java',R/'docs/nochnitsa/source/native-rig.json']
before={str(p):hashlib.sha256(p.read_bytes()).hexdigest() for p in paths}
subprocess.run([sys.executable,'-X','utf8',str(R/'tools/nochnitsa_resources.py')],check=True)
changed=[p for p,h in before.items() if hashlib.sha256(Path(p).read_bytes()).hexdigest()!=h];assert not changed,changed
out=R/'docs/verification/nochnitsa-1.6.4/resource-reproduction.json';out.write_text(json.dumps({'status':'PASS','files_checked':len(paths),'changed_files':changed,'scope':'Full resource tree plus native model and rig source; audio not regenerated by this script'},indent=2)+'\n');print('Resource reproduction PASS, zero changes across',len(paths),'files')
